### WebSocket Route
```typescript
// WebSocket upgrade for room sessions
router.get('/api/room/:roomId/ws', async (request, env) => {
  const { roomId } = request.params;

  // Validate token from query param
  const url = new URL(request.url);
  const token = url.searchParams.get('token');
  if (!token) {
    return new Response('Missing token', { status: 401 });
  }

  const userId = await validateToken(token, env);
  if (!userId) {
    return new Response('Invalid token', { status: 401 });
  }

  // Route to RoomSessionDO
  const doId = env.ROOM_SESSION.idFromName(`session-${roomId}`);
  const stub = env.ROOM_SESSION.get(doId);

  // Forward the upgrade request
  return stub.fetch(new Request('http://internal/websocket', {
    headers: {
      ...Object.fromEntries(request.headers),
      'X-User-Id': userId,
      'X-Room-Id': roomId,
    },
  }));
});
```

