## Task
Create SwarmCoordinator that routes requests to specialized agents and handles multi-intent orchestration.

## Implementation Details

### File Location
`agent-worker/src/agents/SwarmCoordinator.ts`

### SwarmCoordinator Responsibilities
1. **Intent Routing**: Map intents to specialized agents
2. **Multi-Intent Handling**: Parallel execution for compound requests
3. **Response Aggregation**: Combine results from multiple agents
4. **Fallback Handling**: Route to general agent if specialized fails
5. **Context Sharing**: Pass shared context between agents

### Core Implementation
```typescript
class SwarmCoordinator {
  private agents: {
    tasks: TaskAgent;
    budget: BudgetAgent;
    vendors: VendorAgent;
    planning: PlanningAgent;
    collaboration: CollaborationAgent;
    general: GeneralAgent;  // Fallback
  };

  async handle(
    context: AgentContext, 
    intents: Intent[]
  ): Promise<AggregatedResponse> {
    // Single intent: direct route
    if (intents.length === 1) {
      const agent = this.routeToAgent(intents[0]);
      return agent.handle(context, intents[0]);
    }

    // Multi-intent: parallel execution
    const independentIntents = this.classifyDependencies(intents);

    // Execute independent intents in parallel
    const parallelResults = await Promise.all(
      independentIntents.parallel.map(intent => 
        this.routeToAgent(intent).handle(context, intent)
      )
    );

    // Execute dependent intents sequentially
    let sequentialResults = [];
    for (const intent of independentIntents.sequential) {
      const result = await this.routeToAgent(intent).handle(
        { ...context, priorResults: [...parallelResults, ...sequentialResults] },
        intent
      );
      sequentialResults.push(result);
    }

    return this.aggregateResponses([...parallelResults, ...sequentialResults]);
  }

  private routeToAgent(intent: Intent): BaseAgent {
    const INTENT_ROUTES = {
      task_create: 'tasks',
      task_update: 'tasks',
      expense_create: 'budget',
      budget_query: 'budget',
      vendor_search: 'vendors',
      vendor_update: 'vendors',
      milestone_create: 'planning',
      timeline_query: 'planning',
      poll_create: 'collaboration',
      decision_record: 'collaboration',
    };
    return this.agents[INTENT_ROUTES[intent.type] || 'general'];
  }
}
```

