## Task
Create React hook for WebSocket connection with reconnection and state management.

## Implementation Details

### File Location
`web/src/hooks/useAgentWebSocket.ts`

### Hook Interface
```typescript
interface UseAgentWebSocketOptions {
  roomId: string;
  eventId: string;
  onAgentThinking?: (status: string) => void;
  onAgentChunk?: (text: string, index: number) => void;
  onAgentComplete?: (response: AgentResponse) => void;
  onAgentError?: (error: string, recoverable: boolean) => void;
  onToolStart?: (tool: string, params: any) => void;
  onToolComplete?: (tool: string, result: any, success: boolean) => void;
}

interface UseAgentWebSocketReturn {
  invokeAgent: (message: string, parentMessageId?: string) => void;
  isConnected: boolean;
  isInvoking: boolean;
  streamingText: string;  // Accumulated chunks
  activeTools: string[];  // Currently executing tools
  reconnect: () => void;
}

export function useAgentWebSocket(options: UseAgentWebSocketOptions): UseAgentWebSocketReturn;
```

### Implementation
```typescript
export function useAgentWebSocket({
  roomId,
  eventId,
  onAgentThinking,
  onAgentChunk,
  onAgentComplete,
  onAgentError,
  onToolStart,
  onToolComplete,
}: UseAgentWebSocketOptions): UseAgentWebSocketReturn {
  const [isConnected, setIsConnected] = useState(false);
  const [isInvoking, setIsInvoking] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [activeTools, setActiveTools] = useState<string[]>([]);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectAttempts = useRef(0);

  const connect = useCallback(() => {
    const token = getAuthToken();
    const ws = new WebSocket(
      `${WORKER_WS_URL}/api/room/${roomId}/ws?token=${token}`
    );

    ws.onopen = () => {
      setIsConnected(true);
      reconnectAttempts.current = 0;
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);

      switch (data.type) {
        case 'agent_thinking':
          onAgentThinking?.(data.status);
          break;
        case 'agent_chunk':
          setStreamingText(prev => prev + data.text);
          onAgentChunk?.(data.text, data.index);
          break;
        case 'agent_tool_start':
          setActiveTools(prev => [...prev, data.tool]);
          onToolStart?.(data.tool, data.params);
          break;
        case 'agent_tool_complete':
          setActiveTools(prev => prev.filter(t => t !== data.tool));
          onToolComplete?.(data.tool, data.result, data.success);
          break;
        case 'agent_complete':
          setIsInvoking(false);
          setStreamingText('');
          onAgentComplete?.(data.response);
          break;
        case 'agent_error':
          setIsInvoking(false);
          onAgentError?.(data.error, data.recoverable);
          break;
      }
    };

    ws.onclose = () => {
      setIsConnected(false);
      // Exponential backoff reconnection
      const delay = Math.min(1000 * 2 ** reconnectAttempts.current, 30000);
      setTimeout(() => {
        reconnectAttempts.current++;
        connect();
      }, delay);
    };

    wsRef.current = ws;
  }, [roomId, /* callbacks */]);

  // ... lifecycle management

  const invokeAgent = useCallback((message: string, parentMessageId?: string) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      setIsInvoking(true);
      setStreamingText('');
      wsRef.current.send(JSON.stringify({
        type: 'agent_invoke',
        message,
        parentMessageId,
      }));
    }
  }, []);

  return { invokeAgent, isConnected, isInvoking, streamingText, activeTools, reconnect };
}
```

### Reconnection Strategy
- Exponential backoff: 1s, 2s, 4s, 8s... max 30s
- Automatic on disconnect
- Manual reconnect() available
- Auth token refresh on reconnect

