  async handleToolResult(tool: string, result: ToolResult): Promise<void> {
    // Append event
    if (tool === 'convex_crud' && result.success) {
      const event = this.todomainEvent(result);
      await this.eventLog.append(event);

      // Update in-memory state
      this.applyEvent(event);
    }
  }

  private applyEvent(event: DomainEvent): void {
    switch (event.type) {
      case 'TASK_CREATED':
        this.state.tasks.set(event.payload.id, event.payload);
        break;
      case 'TASK_UPDATED':
        const task = this.state.tasks.get(event.payload.taskId);
        if (task) {
          Object.assign(task, event.payload.changes);
        }
        break;
      // ... other event handlers
