## Task
Implement explicit state machine for agent workflow execution.

## Implementation Details

### File Location
`agent-worker/src/agents/WorkflowStateMachine.ts`

### State Definition
```typescript
type WorkflowState =
  | { status: 'idle' }
  | { status: 'receiving'; message: string; receivedAt: number }
  | { status: 'detecting_intent'; message: string; startedAt: number }
  | { status: 'thinking'; intent: Intent; context: AgentContext; iteration: number }
  | { status: 'executing_tool'; tool: string; params: any; startedAt: number }
  | { status: 'awaiting_confirmation'; proposal: Proposal; expiresAt: number }
  | { status: 'streaming'; chunks: string[]; startedAt: number }
  | { status: 'completing'; response: AgentResponse }
  | { status: 'complete'; response: AgentResponse; completedAt: number }
  | { status: 'failed'; error: string; failedAt: number; recoverable: boolean }
  | { status: 'aborted'; reason: string; abortedAt: number };

type WorkflowEvent =
  | { type: 'MESSAGE_RECEIVED'; message: string }
  | { type: 'INTENT_DETECTED'; intent: Intent }
  | { type: 'INTENT_DETECTION_FAILED'; error: string }
  | { type: 'THINKING_STARTED'; iteration: number }
  | { type: 'TOOL_CALL_REQUESTED'; tool: string; params: any }
  | { type: 'TOOL_CALL_COMPLETED'; result: ToolResult }
  | { type: 'TOOL_CALL_FAILED'; error: string }
  | { type: 'PROPOSAL_GENERATED'; proposal: Proposal }
  | { type: 'PROPOSAL_ACCEPTED'; proposalId: string }
  | { type: 'PROPOSAL_REJECTED'; proposalId: string }
  | { type: 'PROPOSAL_EXPIRED'; proposalId: string }
  | { type: 'CHUNK_GENERATED'; text: string }
  | { type: 'RESPONSE_COMPLETE'; response: AgentResponse }
  | { type: 'ERROR_OCCURRED'; error: string; recoverable: boolean }
  | { type: 'ABORT_REQUESTED'; reason: string }
  | { type: 'TIMEOUT'; component: string };
```

### State Machine Implementation
```typescript
export class WorkflowStateMachine {
  private state: WorkflowState = { status: 'idle' };
  private listeners: Set<(state: WorkflowState) => void> = new Set();

  getState(): WorkflowState {
    return this.state;
  }

  transition(event: WorkflowEvent): WorkflowState {
    const nextState = this.reduce(this.state, event);

    if (nextState !== this.state) {
      this.state = nextState;
      this.notifyListeners();
    }

    return this.state;
  }

  private reduce(state: WorkflowState, event: WorkflowEvent): WorkflowState {
    switch (state.status) {
      case 'idle':
        if (event.type === 'MESSAGE_RECEIVED') {
          return { status: 'receiving', message: event.message, receivedAt: Date.now() };
        }
        break;

      case 'receiving':
        if (event.type === 'INTENT_DETECTED') {
          return { 
            status: 'thinking', 
            intent: event.intent, 
            context: {} as AgentContext,  // Filled by handler
            iteration: 0 
          };
        }
        break;

      case 'thinking':
        if (event.type === 'TOOL_CALL_REQUESTED') {
          return { 
            status: 'executing_tool', 
            tool: event.tool, 
            params: event.params, 
            startedAt: Date.now() 
          };
        }
        if (event.type === 'PROPOSAL_GENERATED') {
          return { 
            status: 'awaiting_confirmation', 
            proposal: event.proposal, 
            expiresAt: Date.now() + 5 * 60 * 1000 
          };
        }
        if (event.type === 'RESPONSE_COMPLETE') {
          return { 
            status: 'complete', 
            response: event.response, 
            completedAt: Date.now() 
          };
        }
        break;

      case 'executing_tool':
        if (event.type === 'TOOL_CALL_COMPLETED') {
          // Return to thinking for next iteration
          return { 
            status: 'thinking', 
            intent: (state as any).intent,  // Preserve
            context: (state as any).context,
            iteration: (state as any).iteration + 1 
          };
        }
        if (event.type === 'TOOL_CALL_FAILED') {
          return { 
            status: 'failed', 
            error: event.error, 
            failedAt: Date.now(),
            recoverable: true 
          };
        }
        break;

      case 'awaiting_confirmation':
        if (event.type === 'PROPOSAL_ACCEPTED') {
          return { status: 'thinking', ...state };  // Continue execution
        }
        if (event.type === 'PROPOSAL_REJECTED') {
          return { 
            status: 'complete', 
            response: { text: 'Proposal rejected.' } as AgentResponse,
            completedAt: Date.now() 
          };
        }
        if (event.type === 'PROPOSAL_EXPIRED') {
          return { 
            status: 'aborted', 
            reason: 'Proposal expired', 
            abortedAt: Date.now() 
          };
        }
        break;

      // Handle global events
      default:
        if (event.type === 'ERROR_OCCURRED') {
          return { 
            status: 'failed', 
            error: event.error, 
            failedAt: Date.now(),
            recoverable: event.recoverable 
          };
        }
        if (event.type === 'ABORT_REQUESTED') {
          return { 
            status: 'aborted', 
            reason: event.reason, 
            abortedAt: Date.now() 
          };
        }
    }

    return state;  // No transition
  }

  subscribe(listener: (state: WorkflowState) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private notifyListeners(): void {
    for (const listener of this.listeners) {
      listener(this.state);
    }
  }
}
```

