    pattern: /^create\s+task[:\s]+(.+)$/i,
    intent: 'task_create',
    confidence: 0.90,
    extractor: (m) => ({ title: m[1].trim() }),
  },
  {
    pattern: /^add\s+expense[:\s]+\$?([\d,.]+)\s+(?:for\s+)?(.+)$/i,
    intent: 'expense_create',
    confidence: 0.90,
    extractor: (m) => ({ amount: m[1], description: m[2] }),
  },

  // Search operations
  {
    pattern: /^search\s+(?:for\s+)?(.+?)\s+vendors?(?:\s+in\s+(.+))?$/i,
    intent: 'vendor_search',
    confidence: 0.85,
    extractor: (m) => ({ category: m[1], location: m[2] || '' }),
  },

  // Help
  {
    pattern: /^(help|how do i|what can you do)/i,
    intent: 'help',
    confidence: 0.95,
  },
];

export class FastIntentRouter {
  match(message: string): FastRouteMatch | null {
    const cleaned = message.replace(/@delphi\s*/i, '').trim();

    for (const route of FAST_ROUTES) {
      const match = cleaned.match(route.pattern);
      if (match) {
        return {
          intent: route.intent,
          confidence: route.confidence,
          extractedParams: route.extractor?.(match) || {},
        };
      }
    }

    return null;  // Falls through to next tier
  }
}
