export class RoomSessionDO implements DurableObject {
  private state: DurableObjectState;
  private env: Env;

  constructor(state: DurableObjectState, env: Env) {
    this.state = state;
    this.env = env;
  }

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === '/websocket') {
      return this.handleWebSocketUpgrade(request);
    }

    return new Response('Not Found', { status: 404 });
  }

  async handleWebSocketUpgrade(request: Request): Promise<Response> {
    const upgradeHeader = request.headers.get('Upgrade');
    if (upgradeHeader !== 'websocket') {
      return new Response('Expected websocket', { status: 426 });
    }

    const [client, server] = Object.values(new WebSocketPair());

    // Extract user info from auth token
    const userId = await this.extractUserId(request);
    const roomId = this.extractRoomId(request);

    // Accept with tags for filtering
    this.state.acceptWebSocket(server, [userId, roomId]);

    // Attach metadata that survives hibernation
    server.serializeAttachment({
      userId,
      roomId,
      connectedAt: Date.now(),
    });

    return new Response(null, { status: 101, webSocket: client });
  }

  // Called when WebSocket receives message (wakes from hibernation)
  async webSocketMessage(ws: WebSocket, message: string | ArrayBuffer) {
    const data = JSON.parse(message as string);
    const attachment = ws.deserializeAttachment();

    switch (data.type) {
      case 'agent_invoke':
        await this.handleAgentInvoke(ws, data, attachment);
        break;
      case 'typing_start':
        await this.broadcastTyping(attachment.roomId, attachment.userId, true);
        break;
      case 'typing_stop':
        await this.broadcastTyping(attachment.roomId, attachment.userId, false);
        break;
    }
  }

  async webSocketClose(ws: WebSocket, code: number, reason: string) {
    // Cleanup when client disconnects
    ws.close(code, reason);
  }

  async webSocketError(ws: WebSocket, error: unknown) {
    console.error('WebSocket error:', error);
    ws.close(1011, 'Internal error');
  }
}
