export class EventOrchestratorDO {
  async alarm(): Promise<void> {
    console.log(`[EventDO:${this.eventId}] Alarm triggered`);

    try {
      // 1. Check for due tasks
      await this.checkDueTasks();

      // 2. Send reminder notifications
      await this.sendReminderNotifications();

      // 3. Compress event log (keep last 1000)
      await this.compressEventLog();

      // 4. Sync state to Convex
      await this.syncToConvex();

      // 5. Check vendor follow-ups
      await this.checkVendorFollowups();

      // 6. Update event statistics
      await this.updateStats();

    } catch (error) {
      console.error(`[EventDO:${this.eventId}] Alarm error:`, error);
    }

    // Schedule next alarm (1 minute)
    await this.state.storage.setAlarm(Date.now() + 60_000);
  }

  private async checkDueTasks(): Promise<void> {
    const now = Date.now();
    const dueSoon: Task[] = [];

    for (const task of this.eventState.tasks.values()) {
      if (task.status !== 'completed' && task.deadline) {
        const deadline = new Date(task.deadline).getTime();
        const hoursUntil = (deadline - now) / (1000 * 60 * 60);

        if (hoursUntil <= 24 && hoursUntil > 0) {
          dueSoon.push(task);
        }
      }
    }

    if (dueSoon.length > 0) {
      await this.queueNotification({
        type: 'tasks_due_soon',
        tasks: dueSoon,
        eventId: this.eventId,
      });
    }
  }

  private async compressEventLog(): Promise<void> {
    if (this.eventLog.length > 1000) {
      // Create snapshot of current state
      const snapshot = this.serializeState();
      await this.state.storage.put('stateSnapshot', snapshot);
      await this.state.storage.put('snapshotSequence', this.eventLog.lastSequence);

      // Remove old events from storage
      const oldEvents = this.eventLog.events.slice(0, -1000);
      for (const event of oldEvents) {
        await this.state.storage.delete(`event:${event.sequence}`);
      }

      this.eventLog.events = this.eventLog.events.slice(-1000);
    }
  }

  private async syncToConvex(): Promise<void> {
    // Batch upsert changed entities to Convex
    const changes = this.getUnSyncedChanges();

    if (changes.length > 0) {
      await this.convexClient.mutation(api.agent.batchSync, {
        eventId: this.eventId,
        changes,
      });

      this.markSynced(changes);
    }
  }
}
