interface QueuedNotification {
  type: string;
  payload: any;
  scheduledFor: number;
  attempts: number;
}

private async queueNotification(notification: Omit<QueuedNotification, 'scheduledFor' | 'attempts'>): Promise<void> {
  const queued: QueuedNotification = {
    ...notification,
    scheduledFor: Date.now(),
    attempts: 0,
  };

  // Store in queue
  await this.state.storage.put(
    `notification:${Date.now()}:${Math.random()}`,
    queued
  );
}

private async processNotificationQueue(): Promise<void> {
  const notifications = await this.state.storage.list<QueuedNotification>({ 
    prefix: 'notification:' 
  });

  for (const [key, notification] of notifications) {
    if (notification.scheduledFor <= Date.now()) {
      try {
        await this.sendNotification(notification);
        await this.state.storage.delete(key);
      } catch (error) {
        notification.attempts++;
        if (notification.attempts >= 3) {
          await this.state.storage.delete(key);  // Give up
        } else {
          notification.scheduledFor = Date.now() + 60_000 * notification.attempts;
          await this.state.storage.put(key, notification);
        }
      }
    }
  }
}
