  expense: { weight: 0.3, intents: ['expense_create', 'query_expenses'] },
  cost: { weight: 0.2, intents: ['expense_create', 'query_budget'] },
  paid: { weight: 0.2, intents: ['expense_create'] },
  split: { weight: 0.2, intents: ['expense_create'] },

  // Vendor keywords
  vendor: { weight: 0.3, intents: ['vendor_search', 'query_vendors'] },
  photographer: { weight: 0.25, intents: ['vendor_search'] },
  caterer: { weight: 0.25, intents: ['vendor_search'] },
  dj: { weight: 0.25, intents: ['vendor_search'] },
  florist: { weight: 0.25, intents: ['vendor_search'] },

  // Action keywords (modifiers)
  create: { weight: 0.15, intents: ['task_create', 'expense_create', 'poll_create'] },
  add: { weight: 0.15, intents: ['task_create', 'expense_create'] },
  show: { weight: 0.15, intents: ['query_tasks', 'query_budget', 'query_vendors'] },
  find: { weight: 0.15, intents: ['vendor_search'] },
  search: { weight: 0.2, intents: ['vendor_search'] },
};

export class KeywordHeuristics {
  analyze(message: string): HeuristicScore[] {
    const words = message.toLowerCase().split(/\s+/);
    const intentScores = new Map<string, { score: number; keywords: string[] }>();

    for (const word of words) {
      const weight = KEYWORD_WEIGHTS[word];
      if (weight) {
        for (const intent of weight.intents) {
          const current = intentScores.get(intent) || { score: 0, keywords: [] };
          current.score += weight.weight;
          current.keywords.push(word);
          intentScores.set(intent, current);
        }
      }
    }

    // Normalize and sort
    return Array.from(intentScores.entries())
      .map(([intent, data]) => ({
        intent,
        score: Math.min(data.score, 0.85),  // Cap at 0.85 for heuristics
        keywords: data.keywords,
      }))
      .sort((a, b) => b.score - a.score);
  }
}
