### Streaming Implementation
```typescript
async handleAgentInvoke(
  ws: WebSocket, 
  data: AgentInvokeRequest,
  attachment: ConnectionAttachment
): Promise<void> {
  const { roomId, userId } = attachment;

  try {
    // 1. Indicate thinking
    ws.send(JSON.stringify({ type: 'agent_thinking', status: 'Analyzing request...' }));

    // 2. Get event orchestrator
    const eventDO = this.getEventOrchestrator(await this.getEventId(roomId));

    // 3. Stream agent execution
    const stream = eventDO.streamAgentResponse({
      message: data.message,
      roomId,
      userId,
    });

    for await (const event of stream) {
      switch (event.type) {
        case 'thinking':
          ws.send(JSON.stringify({ type: 'agent_thinking', status: event.status }));
          break;
        case 'tool_start':
          ws.send(JSON.stringify({ type: 'agent_tool_start', ...event }));
          break;
        case 'tool_complete':
          ws.send(JSON.stringify({ type: 'agent_tool_complete', ...event }));
          break;
        case 'chunk':
          ws.send(JSON.stringify({ type: 'agent_chunk', text: event.text, index: event.index }));
          break;
      }
    }

    // 4. Final response
    ws.send(JSON.stringify({ type: 'agent_complete', response: stream.result }));

  } catch (error) {
    ws.send(JSON.stringify({ 
      type: 'agent_error', 
      error: error.message,
      recoverable: this.isRecoverable(error)
    }));
  }
}
```

